{
  "root": "main_stack",
  "state": {
    "comparison_data": [
      {
        "Feature": "Speed (Read/Write)",
        "SSD": "Significantly faster. SATA SSDs offer speeds of around 500-550 MB/s, while NVMe SSDs (connected via PCIe) can reach 3,500 MB/s to over 7,000 MB/s.",
        "HDD": "Slower. Typically offers sequential read/write speeds between 80-160 MB/s."
      },
      {
        "Feature": "Durability",
        "SSD": "Highly durable as they have no moving parts. They are resistant to drops, shocks, and vibrations, making them ideal for laptops.",
        "HDD": "Less durable due to mechanical spinning platters and read/write heads. They are susceptible to damage from physical impacts."
      },
      {
        "Feature": "Cost per GB",
        "SSD": "Generally higher cost per gigabyte (e.g., $0.08 - $0.15 per GB).",
        "HDD": "Significantly lower cost per gigabyte (e.g., $0.02 - $0.04 per GB), making them cost-effective for large storage needs."
      },
      {
        "Feature": "Technology",
        "SSD": "Uses NAND flash memory to store data electronically.",
        "HDD": "Uses spinning platters coated with magnetic material and read/write heads to store data magnetically."
      },
      {
        "Feature": "Power Consumption",
        "SSD": "Lower power consumption, leading to better battery life in laptops and less heat generation.",
        "HDD": "Higher power consumption due to mechanical components."
      },
      {
        "Feature": "Noise",
        "SSD": "Silent operation as there are no moving parts.",
        "HDD": "Audible noise from spinning platters and moving read/write heads."
      },
      {
        "Feature": "Form Factors",
        "SSD": "Available in 2.5-inch SATA, M.2 SATA, M.2 NVMe, and PCIe add-in cards.",
        "HDD": "Primarily 3.5-inch for desktops and 2.5-inch for laptops."
      },
      {
        "Feature": "Boot/Load Times",
        "SSD": "Much faster boot times for operating systems and quicker loading of applications and games.",
        "HDD": "Slower boot and application load times."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title",
        "intro_text",
        "comparison_card",
        "conclusion_text",
        "action_button"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "SSD vs. HDD: A Detailed Comparison",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Choosing between a Solid State Drive (SSD) and a Hard Disk Drive (HDD) is crucial for your computer's performance and storage needs. Here's a breakdown of their key differences:",
        "variant": "body"
      },
      "children": []
    },
    "comparison_card": {
      "type": "Card",
      "props": {},
      "children": [
        "comparison_table_title",
        "comparison_table"
      ]
    },
    "comparison_table_title": {
      "type": "Text",
      "props": {
        "text": "Feature Comparison",
        "variant": "h3"
      },
      "children": []
    },
    "comparison_table": {
      "type": "Table",
      "props": {
        "statePath": "/comparison_data",
        "columns": [
          {
            "key": "Feature",
            "label": "Feature"
          },
          {
            "key": "SSD",
            "label": "SSD"
          },
          {
            "key": "HDD",
            "label": "HDD"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "Feature"
      },
      "children": []
    },
    "conclusion_text": {
      "type": "Text",
      "props": {
        "text": "Ultimately, the best choice depends on your priorities: speed and durability (SSD) or large capacity at a lower cost (HDD).",
        "variant": "body"
      },
      "children": []
    },
    "action_button": {
      "type": "Button",
      "props": {
        "label": "Explore Storage Options"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.example.com/storage-solutions"
          }
        }
      }
    }
  }
}
